<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { staffApi as api } from '../../features/live/api';
import PreviewSelect from '../../features/preview/components/PreviewSelect.vue';
import TableFooter from '../../features/preview/components/TableFooter.vue';
import { dateOf } from '../../features/workbench/types';
interface TraceRow {trace_id:string;kind:string;conversation_id:number|null;query:string;route:string;status:string;outcome:string;model:string;handoff:boolean;capture_complete:boolean;final_reply:string;error:string|null;started_at:string;latency_ms:number}
interface Node {id:number;name:string;type:string;location:string;status:string;model:string;latency_ms:number;attempt:number;usage:{normalized?:{input_tokens:number|null;output_tokens:number|null;total_tokens:number|null}};payloads:Record<string,unknown>;error:string|null}
interface TraceDetail extends TraceRow {nodes:Node[];context_sources:unknown;capture_errors:string[]}
const props=defineProps<{initialId?:string}>();
const rows=ref<TraceRow[]>([]),total=ref(0),page=ref(1),kind=ref(''),error=ref(''),loading=ref(false),drawer=ref(false),detail=ref<TraceDetail|null>(null),detailBusy=ref(false);
const usage=ref<{known_total_tokens:number;complete:boolean;missing_usage_calls:number;call_count:number}|null>(null);
const labels:Record<string,string>={question:'客户问答',recall_test:'召回测试',config_check:'配置校验',ingestion:'知识处理',summary:'会话摘要',assist:'回复辅助',comfort:'等待安抚'};
const statuses:Record<string,string>={SUCCESS:'已完成',FAILED:'失败',SUPERSEDED:'已丢弃过期结果',RUNNING:'处理中'};
let timer:ReturnType<typeof setInterval>|undefined,disposed=false,version=0;
const callTotal=computed(()=>detail.value?.nodes.filter(n=>n.location==='remote_ai').reduce((n,node)=>n+(node.usage.normalized?.total_tokens||0),0)||0);
const missing=computed(()=>!!detail.value&&(!detail.value.capture_complete||detail.value.nodes.some(n=>n.location==='remote_ai'&&nodeUsage(n)===null)));
const nodeUsage=(n:Node)=>n.usage.normalized?.total_tokens??null;
async function load(){if(loading.value)return;loading.value=true;try{const result=await api<{items:TraceRow[];total:number}>(`/api/admin/traces?page=${page.value}&page_size=8&kind=${encodeURIComponent(kind.value)}`);if(!disposed){rows.value=result.items;total.value=result.total;error.value='';}}catch(e){if(!disposed)error.value=(e as Error).message;}finally{loading.value=false;}}
async function open(id:string){drawer.value=true;detailBusy.value=true;detail.value=null;usage.value=null;const request=++version;
 try{const result=await api<TraceDetail>(`/api/admin/traces/${id}`);if(disposed||request!==version)return;detail.value=result;
  if(result.conversation_id){const value=await api<typeof usage.value>(`/api/agent/conversations/${result.conversation_id}/usage`);if(request===version&&!disposed)usage.value=value;}
 }catch(e){if(!disposed)error.value=(e as Error).message;}finally{if(request===version)detailBusy.value=false;}}
watch(kind,()=>{page.value=1;void load();});watch(page,load);watch(()=>props.initialId,id=>{if(id)void open(id);});
onMounted(async()=>{await load();if(props.initialId)await open(props.initialId);timer=setInterval(()=>{if(rows.value.some(r=>r.status==='RUNNING'))void load();},3000);});
onUnmounted(()=>{disposed=true;version++;clearInterval(timer);});
</script>
<template><div class="pv-page live-page"><div class="live-page-heading"><div><h1>调用记录</h1><p>查看真实模型请求、检索来源与用量；知识处理和测试与客户接待分开统计。</p></div><button class="wb-btn" :disabled="loading" @click="load">刷新</button></div><p v-if="error" class="live-error" role="alert">{{error}}</p><section class="pv-card"><div class="pv-filters"><PreviewSelect v-model="kind" aria-label="调用类型"><option value="">全部类型</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></PreviewSelect><span class="live-muted">会话摘要及其重试不计入会话 Token 总量</span></div><div class="pv-table-scroll"><table class="pv-table"><thead><tr><th>问题 / 任务</th><th>类型</th><th>状态</th><th>模型</th><th>开始时间 / 耗时</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.trace_id"><td class="pv-wide-cell"><strong>{{row.query}}</strong><small>{{row.conversation_id?`会话 #${row.conversation_id}`:'独立处理'}}</small></td><td>{{labels[row.kind]||row.kind}}</td><td><span class="pv-tag" :class="row.status==='SUCCESS'?'green':row.status==='FAILED'?'amber':''">{{statuses[row.status]||row.status}}</span><small v-if="row.handoff">已转人工等待</small><small v-if="!row.capture_complete">记录不完整</small></td><td>{{row.model||'按配置调用'}}</td><td>{{dateOf(row.started_at)}}<small>{{(row.latency_ms/1000).toFixed(2)}} 秒</small></td><td><button class="wb-text-button" @click="open(row.trace_id)">查看详情</button></td></tr></tbody></table></div><div v-if="!rows.length" class="pv-empty"><strong>{{loading?'正在读取记录…':'暂无调用记录'}}</strong></div><TableFooter v-model:page="page" :total="total"/></section>
<el-drawer v-model="drawer" title="调用详情" size="min(840px, 100vw)" class="wb-history-drawer"><p v-if="detailBusy" class="live-muted">正在读取调用过程…</p><template v-if="detail"><div class="live-trace-summary"><span class="pv-tag">{{labels[detail.kind]||detail.kind}}</span><span class="pv-tag">{{statuses[detail.status]||detail.status}}</span><h2>{{detail.query}}</h2><p>{{detail.final_reply||'此记录不包含对客回答'}}</p><small>{{detail.trace_id}}</small><p class="live-muted">本次调用已知 Token：{{callTotal}}{{missing?'（部分用量未报告）':''}}</p><p v-if="usage" class="live-muted">本次接待已知 Token：{{usage.known_total_tokens}}{{usage.complete?'':'（记录或用量不完整）'}} · {{usage.call_count}} 次模型请求 · 不含摘要与测试</p><p v-if="detail.error" class="live-error">{{detail.error}}</p></div><article v-for="node in detail.nodes" :key="node.id" class="live-trace-node"><div><strong>{{node.name}}</strong><span class="pv-tag" :class="node.status==='SUCCESS'?'green':'amber'">{{statuses[node.status]||node.status}}</span></div><p class="live-muted">{{node.location==='remote_ai'?node.model:'程序校验'}} · {{node.latency_ms}} 毫秒<template v-if="node.location==='remote_ai'"> · 第 {{node.attempt}} 次请求 · Token {{nodeUsage(node)??'供应商未报告'}}</template></p><details><summary>查看输入与输出</summary><pre>{{JSON.stringify(node.payloads,null,2)}}</pre></details><p v-if="node.error" class="live-inline-error">{{node.error}}</p></article></template></el-drawer></div></template>
